<script setup lang="ts">
const { data, refresh } = await useWorkspace()
const modal = ref(false), busy = ref(false), error = ref(''), search = ref('')
const form = reactive({ name: '', source: 'manifest', reference: '', config: 'ta_in', labelOrigin: 'unknown', description: '' })
const filtered = computed(() => data.value.datasets.filter(d => `${d.name} ${d.reference}`.toLowerCase().includes(search.value.toLowerCase())))
async function save() { busy.value = true; error.value = ''; try { await $fetch('/api/datasets', { method: 'POST', body: form }); await refresh(); modal.value = false; useNotice().notify('Dataset registered'); form.name = ''; form.reference = ''; form.description = '' } catch (e) { error.value = apiError(e) } finally { busy.value = false } }
</script>
<template><div class="page-heading"><div><span class="eyebrow">BETTER DATA, BETTER MODELS</span><h1>Datasets<span class="title-dot">.</span></h1><p>Your training material, with its context intact.</p></div><button class="button primary" @click="modal = true; error = ''"><AppIcon name="Plus" />Register dataset</button></div><div class="toolbar"><span class="section-count">{{ data.datasets.length }} datasets</span><label class="search-box"><AppIcon name="Search" :size="17"/><input v-model="search" aria-label="Search datasets" placeholder="Search datasets…" /></label></div><div v-if="filtered.length" class="resource-grid"><article v-for="dataset in filtered" :key="dataset.id" class="panel resource-card"><div class="resource-top"><span class="resource-icon blue"><AppIcon name="Database" :size="25" /></span><span class="pill">{{ dataset.source === 'manifest' ? 'JSONL manifest' : 'Hugging Face' }}</span></div><h2>{{ dataset.name }}</h2><p>{{ dataset.description || 'Tamil speech recognition dataset' }}</p><div class="reference-box mono">{{ dataset.reference }}</div><div class="label-origin"><AppIcon :name="dataset.labelOrigin === 'human' ? 'CheckCheck' : 'CircleHelp'" :size="16" />{{ dataset.labelOrigin === 'teacher' ? 'AI teacher labels · not human ground truth' : `${dataset.labelOrigin} label provenance` }}</div><div class="resource-footer"><span>{{ dataset.source === 'manifest' ? 'Validated on the worker before training' : `Configuration: ${dataset.config}` }}</span></div></article></div><section v-else class="panel"><EmptyState icon="Database" :title="search ? 'No matching datasets' : 'Every good run starts with good data'" :description="search ? 'Try another dataset name.' : 'Register an existing audio manifest on your GPU server, or use Tamil FLEURS from Hugging Face.'"><button v-if="!search" class="button secondary" @click="modal = true">Register your first dataset<AppIcon name="Plus" :size="16" /></button></EmptyState></section><AppModal v-if="modal" title="Register a dataset" subtitle="Reference existing data without copying your audio into the dashboard." @close="modal = false"><form @submit.prevent="save"><label class="field">Dataset name<input v-model="form.name" required minlength="2" maxlength="100" placeholder="Tamil call recordings v1" /></label><label class="field">Source<select v-model="form.source"><option value="manifest">JSONL manifest on worker</option><option value="huggingface">Hugging Face · FLEURS</option></select></label><label class="field">{{ form.source === 'manifest' ? 'Manifest path on worker' : 'Dataset repository' }}<input v-model="form.reference" required :placeholder="form.source === 'manifest' ? '/datasets/calls/manifest.jsonl' : 'google/fleurs'" /></label><div v-if="form.source === 'manifest'" class="form-hint">Each row needs <code>id</code>, <code>audio</code>, <code>text</code>, and <code>duration</code>. Audio paths resolve relative to the manifest. Use speaker IDs in the form <code>speaker_utterance</code>.</div><div v-else class="alert info">The initial recipe supports <strong>google/fleurs · ta_in</strong>. It uses train + validation for training and test for evaluation, matching your existing script. Repeated tuning requires a separate final test set.</div><label class="field">Transcript provenance<select v-model="form.labelOrigin"><option value="unknown">Unknown / not reviewed</option><option value="human">Human verified</option><option value="teacher">AI teacher generated</option><option value="mixed">Mixed human and AI labels</option></select></label><label class="field">Notes <span class="optional">optional</span><textarea v-model="form.description" rows="2" placeholder="Recording conditions, language mix, dataset version…" /></label><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Saving…' : 'Register dataset' }}</button></div></form></AppModal></template>
